import{_ as a,o as n,c as t,ae as r}from"./chunks/framework.Dn6zxbF8.js";const p=JSON.parse('{"title":"Asana: hierarchy, audiences, and access","description":"","frontmatter":{},"headers":[],"relativePath":"adrs/1917971986/references/asana.md","filePath":"adrs/1917971986/references/asana.md"}'),s={name:"adrs/1917971986/references/asana.md"};function i(o,e,l,c,h,d){return n(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="asana-hierarchy-audiences-and-access" tabindex="-1">Asana: hierarchy, audiences, and access <a class="header-anchor" href="#asana-hierarchy-audiences-and-access" aria-label="Permalink to &quot;Asana: hierarchy, audiences, and access&quot;">​</a></h1><p>Verified against primary documentation on 2026-10-10.</p><p>The Asana Help Center renders its articles in the browser, so its pages were read through rendered excerpts rather than raw page text. Claims that no readable Asana page states are marked as not documented.</p><h2 id="hierarchy" tabindex="-1">Hierarchy <a class="header-anchor" href="#hierarchy" aria-label="Permalink to &quot;Hierarchy&quot;">​</a></h2><p>Asana&#39;s top container is either an Organization or a Workspace, and an account has one or the other, not both nested. An Organization forms around a verified company email domain: anyone who signs up with that domain automatically becomes a member. A Workspace has no domain tie, is used for personal work or for a company without a unique domain, and behaves like a single team rather than a structure that contains teams. (<a href="https://asana.com/faq.md" target="_blank" rel="noreferrer">Asana FAQ</a>)</p><p>Inside an Organization, Teams group people and the projects they work on. Divisions sit above Teams on Enterprise and Enterprise plus plans, letting an organization split users into administrative groups for license assignment and delegated administration, while organization admins and super admins retain access across every division. (<a href="https://help.asana.com/s/article/divisions-in-paid-orgs" target="_blank" rel="noreferrer">Divisions in paid orgs</a>)</p><p>Below Teams, Projects hold the work, and Portfolios (Advanced, Enterprise, and Enterprise plus plans) are a separate, flatter construct: a portfolio is a collection of projects for monitoring status and progress across them, not a position in the containment tree, and projects do not nest inside other projects. (<a href="https://help.asana.com/s/article/portfolio-management" target="_blank" rel="noreferrer">Portfolio management</a>)</p><p>Tasks are not confined to one project. A task can be multi-homed into several projects across any teams in the organization, so it is one record that shows up in every project it is added to, not a copy. (<a href="https://help.asana.com/s/article/how-to-multi-home-tasks" target="_blank" rel="noreferrer">How to multi-home tasks</a>)</p><h2 id="governance-and-work" tabindex="-1">Governance and work <a class="header-anchor" href="#governance-and-work" aria-label="Permalink to &quot;Governance and work&quot;">​</a></h2><p>Organization membership, the admin console, and billing live at the Organization level and are tied to the verified email domain. Billing and license administration can be delegated to Division admins, but oversight of every division remains with organization admins and super admins. (<a href="https://help.asana.com/s/article/divisions-in-paid-orgs" target="_blank" rel="noreferrer">Divisions in paid orgs</a>)</p><p>Work itself, meaning Teams, Projects, and the tasks inside them, lives below the Organization. A Workspace, when a company has no verified domain, holds both governance (its own member list) and work in one undivided layer, since Asana does not split a Workspace into a governing root and a working layer the way it does for an Organization. (<a href="https://asana.com/faq.md" target="_blank" rel="noreferrer">Asana FAQ</a>)</p><h2 id="audiences-and-visibility" tabindex="-1">Audiences and visibility <a class="header-anchor" href="#audiences-and-visibility" aria-label="Permalink to &quot;Audiences and visibility&quot;">​</a></h2><p>Asana documents an object-based privacy model that applies to Teams and Projects, with privacy flowing from the top down so that organization and team settings constrain project settings. (<a href="https://help.asana.com/s/article/understanding-privacy-and-visibility-in-asana" target="_blank" rel="noreferrer">Understanding privacy and visibility in Asana</a>)</p><p>Team privacy has three named settings: Membership by Request (accessible to team members, others may request to join and an active member or team admin must approve), Private (accessible to team members only, no requests accepted), and Public to organization (accessible to team and organization members, others may request to join). Public and private team options require a paid tier. (<a href="https://help.asana.com/s/article/team-permissions" target="_blank" rel="noreferrer">Team permissions</a>)</p><p>Project privacy has three named settings: Private to members (accessible only to invited project members, non-members cannot see the project in search), Team only (accessible to the project&#39;s team), and Shared with organization (accessible to project members, team members, and every organization member). Shared with organization is available only in paid organizations and not on a Division subscription. (<a href="https://help.asana.com/s/article/project-permissions" target="_blank" rel="noreferrer">Project permissions</a>)</p><p>Guests, meaning people without an email address on the organization&#39;s approved domain, have limited access and see only what is explicitly shared with them. A guest can join a team only by invitation and cannot create, browse, or request to join additional teams. Asana also names &quot;limited access members,&quot; people who lack access to every project in a team they belong to; they can still see the team&#39;s name and membership. (<a href="https://help.asana.com/s/article/guests-faq" target="_blank" rel="noreferrer">Guests FAQ</a>)</p><h2 id="narrowing-below-a-parent" tabindex="-1">Narrowing below a parent <a class="header-anchor" href="#narrowing-below-a-parent" aria-label="Permalink to &quot;Narrowing below a parent&quot;">​</a></h2><p>A project can narrow its audience below what its team or organization would otherwise allow by choosing Private to members or Team only instead of Shared with organization, restricting access to a subset of the people who could otherwise reach it through the team. (<a href="https://help.asana.com/s/article/project-permissions" target="_blank" rel="noreferrer">Project permissions</a>)</p><p>A team can likewise narrow itself to Private even inside an organization whose other teams are open, limiting discovery and membership to people explicitly invited. (<a href="https://help.asana.com/s/article/team-permissions" target="_blank" rel="noreferrer">Team permissions</a>)</p><h2 id="ceilings-from-above" tabindex="-1">Ceilings from above <a class="header-anchor" href="#ceilings-from-above" aria-label="Permalink to &quot;Ceilings from above&quot;">​</a></h2><p>Asana places organization-wide sharing controls with admins. Admins &quot;can set default sharing permissions, restrict public links, and control who sees or shares projects and reports,&quot; and super admins &quot;can enforce consistent permissions at scale by setting and governing permission defaults across the organization&quot; (<a href="https://asana.com/features/admin-security/permissions" target="_blank" rel="noreferrer">Admin permissions and access controls</a>). Organization settings influence team settings, which in turn influence project settings (<a href="https://help.asana.com/s/article/understanding-privacy-and-visibility-in-asana" target="_blank" rel="noreferrer">Understanding privacy and visibility</a>). Whether an admin can remove the Shared with organization option from every project, rather than only change its default, is not documented on a publicly readable Asana page.</p><h2 id="discovery-versus-access" tabindex="-1">Discovery versus access <a class="header-anchor" href="#discovery-versus-access" aria-label="Permalink to &quot;Discovery versus access&quot;">​</a></h2><p>Asana&#39;s privacy settings tie discovery to access rather than separating them: a Private to members project does not appear in non-members&#39; search results, and a Private team does not accept requests to join. Membership by Request teams make an explicit middle case, where the team is discoverable enough to request access but the request requires approval before membership is granted. (<a href="https://help.asana.com/s/article/team-permissions" target="_blank" rel="noreferrer">Team permissions</a>, <a href="https://help.asana.com/s/article/project-permissions" target="_blank" rel="noreferrer">Project permissions</a>)</p><h2 id="small-customers" tabindex="-1">Small customers <a class="header-anchor" href="#small-customers" aria-label="Permalink to &quot;Small customers&quot;">​</a></h2><p>A personal or domain-less account gets a Workspace, which behaves like a single team and carries no organization switcher, division structure, or domain-based admin console. Converting to an Organization requires adding a company email address to the account and verifying that domain&#39;s ownership through a DNS TXT record before Asana allows the conversion. (<a href="https://asana.com/faq.md" target="_blank" rel="noreferrer">Asana FAQ</a>; <a href="https://help.asana.com/s/article/email-domain-management-for-asana-organizations" target="_blank" rel="noreferrer">Email domain management for Asana organizations</a>)</p><h2 id="consolidation" tabindex="-1">Consolidation <a class="header-anchor" href="#consolidation" aria-label="Permalink to &quot;Consolidation&quot;">​</a></h2><p>Each email domain can be associated with only one Organization at a time, and an Organization can hold multiple domains but a domain cannot be shared across multiple organizations. Asana support resolves conflicts when a domain is already tied to an existing organization, which indicates there is no self-service merge between organizations built around the same domain. (<a href="https://help.asana.com/s/article/email-domain-management-for-asana-organizations" target="_blank" rel="noreferrer">Email domain management for Asana organizations</a>)</p><h2 id="relevance-to-this-adr" tabindex="-1">Relevance to this ADR <a class="header-anchor" href="#relevance-to-this-adr" aria-label="Permalink to &quot;Relevance to this ADR&quot;">​</a></h2><ul><li>Asana&#39;s Organization (domain-bound) versus Workspace (domain-less) split maps onto the ADR&#39;s single root that is sometimes hidden: a one-workspace Asana customer never deals with organization-level structure, matching &quot;a one-workspace customer never sees the organization,&quot; though Asana reaches this by giving domain-less customers a different top-level object entirely rather than by revealing an always-present root on the second workspace.</li><li>Asana&#39;s Team sits where this ADR places Folder and partially where it places Workspace: teams hold visibility settings and contain projects, while tasks can be multi-homed across projects, so a task in Asana has no single position the way a resource with one <code>parent</code> does in this ADR.</li><li>Asana&#39;s per-level privacy settings (team privacy, project privacy) and its statement that privacy flows top-down agree with the ADR&#39;s rule that ancestors&#39; limits cap descendants and that any level may narrow below its parent.</li><li>Asana&#39;s admin-governed sharing defaults resemble this ADR&#39;s root ceilings, but the public pages describe defaults rather than enforced caps, so they do not confirm the opt-in enforcement this ADR calls for.</li><li>Asana diverges from the ADR on consolidation and on &quot;project&quot;: Asana ties organization identity to an email domain rather than to an explicit migration decision, and Asana&#39;s Portfolio is a cross-project rollup with no parent position, unlike this ADR, where nothing above Project is named &quot;project&quot; and Folder, not Portfolio, is the grouping construct.</li></ul><h2 id="sources" tabindex="-1">Sources <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;Sources&quot;">​</a></h2><ul><li><a href="https://asana.com/faq.md" target="_blank" rel="noreferrer">Asana Frequently Asked Questions (asana.com/faq.md)</a></li><li><a href="https://help.asana.com/s/article/divisions-in-paid-orgs" target="_blank" rel="noreferrer">Divisions in paid orgs</a></li><li><a href="https://help.asana.com/s/article/portfolio-management" target="_blank" rel="noreferrer">Portfolio management</a></li><li><a href="https://help.asana.com/s/article/how-to-multi-home-tasks" target="_blank" rel="noreferrer">How to multi-home tasks</a></li><li><a href="https://help.asana.com/s/article/understanding-privacy-and-visibility-in-asana" target="_blank" rel="noreferrer">Understanding privacy and visibility in Asana</a></li><li><a href="https://help.asana.com/s/article/team-permissions" target="_blank" rel="noreferrer">Team permissions</a></li><li><a href="https://help.asana.com/s/article/project-permissions" target="_blank" rel="noreferrer">Project permissions</a></li><li><a href="https://help.asana.com/s/article/guests-faq" target="_blank" rel="noreferrer">Guests FAQ</a></li><li><a href="https://help.asana.com/s/article/email-domain-management-for-asana-organizations" target="_blank" rel="noreferrer">Email domain management for Asana organizations</a></li><li><a href="https://asana.com/features/admin-security/permissions" target="_blank" rel="noreferrer">Admin permissions and access controls</a></li></ul>',31)])])}const g=a(s,[["render",i]]);export{p as __pageData,g as default};
